import sys
sys.path.insert(0, '.')
try:
    from hae.genome.schema import CompanyGenome, DepartmentGenome, AgentGenome
    from hae.genome.morphogenesis import StructuralCrossoverEngine
except ImportError as e:
    print(f'IMPORT_ERROR: {e}')
    sys.exit(1)

# Construct minimal valid parents
def make_agent(role):
    return AgentGenome(role=role, goal='g', backstory='b', backstory_traits=['t'], temperature=0.5)

def make_dept(dept_id, name, mandate):
    mgr = make_agent('manager')
    agt = make_agent('worker')
    return DepartmentGenome(dept_id=dept_id, name=name, mandate=mandate, manager=mgr, agents=[agt])

def make_company(cid, depts):
    ceo = make_agent('ceo')
    return CompanyGenome(company_id=cid, ceo=ceo, departments=depts, budget_usd=1.0)

# Parent A: Systems Eng
dept_a = make_dept('dept_systems_eng', 'Systems', 'systems engineering')
comp_a = make_company('comp_a', [dept_a])

# Parent B: QA
dept_b = make_dept('dept_qa_redteam', 'QA', 'qa testing')
comp_b = make_company('comp_b', [dept_b])

engine = StructuralCrossoverEngine()
try:
    child = engine.recombine(comp_a, comp_b, 'child_1', 1)
    for d in child.departments:
        if d.dept_id == 'dept_systems_eng':
            if d.manager is None:
                print('FAIL: Manager is None')
            else:
                print('PASS: Manager exists')
except Exception as e:
    print(f'EXCEPTION: {type(e).__name__}: {e}')

